    std::cout << "store: saving " << data << "\n";
    auditor_.log("save: " + data);
}

void DataStore::purge() {
    std::cout << "store: purging\n";
    auditor_.log("purge");
}

std::string DataStore::query() {
    std::cout << "store: querying\n";
    return "stored-data";
}

} // namespace store
